-- Arias PAM — carga inicial de Cuadros Eléctricos BT
-- Fuente: R-SSTT-01-08 CUADROS BT v0(9).xlsx / hoja SSTT BT
-- Se cargan las posiciones 1-40. Las posiciones 41-60 del Excel están vacías y no se crean.
-- La posición 7 se conserva porque existe en el Excel, aunque CUADRO está vacío.
-- Las fechas de instalación/revisión no se inventan: el Excel no las contiene.
-- Los checks se cargan pendientes porque las 10 celdas de comprobación del Excel están vacías.
-- El estado OPERATIVE es un valor inicial de Arias PAM; NO procede del Excel.

begin;

alter table public.electrical_panels
  add column if not exists excel_id integer;

alter table public.electrical_panels
  add column if not exists source_document text;

-- Preflight: esta consulta debe devolver 0 filas antes del índice único.
select code, count(*) as total
from public.electrical_panels
group by code
having count(*) > 1
order by code;

create unique index if not exists ux_electrical_panels_code
  on public.electrical_panels (code);

create unique index if not exists ux_electrical_panels_excel_id
  on public.electrical_panels (excel_id)
  where excel_id is not null;

-- Vincular por código cualquier registro de prueba ya existente CBT-001..CBT-040.
with imported(code, excel_id) as (
  values
    ('CBT-001', 1),
    ('CBT-002', 2),
    ('CBT-003', 3),
    ('CBT-004', 4),
    ('CBT-005', 5),
