on conflict (excel_id) where excel_id is not null do update set
  code = excluded.code,
  name = excluded.name,
  location = excluded.location,
  source_document = excluded.source_document,
  updated_at = now();

commit;

select excel_id, code, name, location
from public.electrical_panels
where excel_id between 1 and 40
order by excel_id;
